import {createRun,jump,releaseJump,slide,releaseSlide,step,STEP,PLAYER_X,TYPES,BIOMES,dailySeed,flowMultiplier} from './engine.js';
import {GameAudio} from './audio.js';
import {asset,createRenderer} from './render.js';
const $=s=>document.querySelector(s),overlay=$('#overlay'),canvas=$('#game'),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const placeholder='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256"><rect width="256" height="256" fill="#244239"/><text x="128" y="150" text-anchor="middle" font-size="80" fill="#d8e99a">?</text></svg>');
const fallback=[{id:'1',name:'The Aberration',segment:'Planeswalkers',image:'assets/chimp-1.webp'},{id:'2',name:'The Achromatic',segment:'Proletariat',image:'assets/chimp-2.webp'},{id:'3',name:'The Adolescent',segment:'Proletariat',image:'assets/chimp-3.webp'}];
const defaultSave=()=>({version:2,sound:true,selected:'1',favorites:[],tutorial:false,achievements:[],runs:[],perCharacter:{},daily:{},bestSplits:[],recent:[]});
let data=defaultSave();try{const modern=JSON.parse(localStorage.getItem('chimpions-save-v2')||'null');if(modern&&modern.version===2)data={...data,...modern};else{const legacy=JSON.parse(localStorage.getItem('chimpions-runs')||'[]');if(Array.isArray(legacy))data.runs=legacy;data.selected=localStorage.getItem('chimpions-selected')||'1';data.sound=localStorage.getItem('chimpions-sound')!=='false'}}catch{}
let collection=fallback,selected=fallback[0],state='menu',run=createRun(),previous='running',countdown=0,raf=0,last=0,acc=0,particles=[],newRecord=false,runBestBefore=0,runBestDistance=0,announcedBest=false,bestMilestones=new Set(),tutorialActive=false;
const renderer=createRenderer(canvas),voice=new GameAudio(data.sound),pad=n=>String(Math.floor(n)).padStart(6,'0'),best=()=>data.runs[0]?.score||0;
function persist(){try{data.selected=selected.id;data.runs=data.runs.filter(x=>Number.isFinite(x.score)&&Number.isFinite(x.distance)).sort((a,b)=>b.score-a.score).slice(0,10);data.recent=[selected.id,...data.recent.filter(x=>x!==selected.id)].slice(0,12);localStorage.setItem('chimpions-save-v2',JSON.stringify(data));localStorage.setItem('chimpions-runs',JSON.stringify(data.runs.slice(0,5)));localStorage.setItem('chimpions-selected',selected.id);localStorage.setItem('chimpions-sound',String(data.sound))}catch{}}
function imageTag(c,extra=''){return`<img src="${escape(c.image)}" alt="${escape(c.name)}" ${extra}>`}
document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement&&!e.target.dataset.fallback){e.target.dataset.fallback='1';e.target.src=placeholder}},true);
function tone(kind){voice.enabled=data.sound;voice.play(kind);if(voice.failed){data.sound=false;$('#sound').textContent='Sound unavailable'}}
function syncDashAudio(){voice.enabled=data.sound;voice.setDash?.(state==='running'&&run.y===0&&(run.slideHeld||run.slideMin>0))}
function updateMate(){$('#mate').innerHTML=imageTag(selected)+`<span>${escape(selected.name)}<small>${escape(selected.segment)}</small></span>`;$('#personalBest').innerHTML=pad(best())+' <small>PTS</small>';$('#sound').textContent=data.sound?'♫ Sound on':'♪ Sound off';asset(selected.image)}
function mode(s){voice.setDash?.(false);releaseControls();state=s;overlay.dataset.mode=s;$('#hud').hidden=!['running','paused','countdown','over'].includes(s);$('#runExtras').hidden=!['running','paused','countdown','over'].includes(s);$('#touchControls').hidden=s!=='running';cancelAnimationFrame(raf);raf=0;last=0;acc=0;if(['intro','running','countdown'].includes(s))raf=requestAnimationFrame(loop);else draw()}
function menu(){mode('menu');overlay.innerHTML=`<div class="menu"><span class="tag">INTO THE WILD</span><h1>CHIMPIONS<br><span>DASH ↗</span></h1><p>Run. Jump. Slide. Find your flow.</p><div class="menu-actions"><button class="primary" data-action="start">▶ &nbsp; PLAY</button><button data-action="daily">☀ DAILY JUNGLE</button><button data-action="choose">Choose Chimpion</button></div><div class="menu-links"><button class="textbutton" data-action="help">How to play</button><button class="textbutton" data-action="scores">♜ My best</button></div>${imageTag(selected,'class="hero-chimp"')}</div>`;updateMate()}
function choose(){mode('choose');const segments=[...new Set(collection.map(c=>c.segment).filter(Boolean))].sort();overlay.innerHTML=`<div class="panel"><div class="panel-head"><h2>CHOOSE YOUR CHIMPION</h2><button class="small" data-action="menu">Back</button></div><div class="filters"><input class="search" id="search" aria-label="Search Chimpions" placeholder="Find your Chimpion…"><select id="segment" aria-label="Filter by segment"><option value="">All tribes</option>${segments.map(x=>`<option>${escape(x)}</option>`).join('')}</select><label><input id="favoritesOnly" type="checkbox"> Favorites</label></div><div class="grid" id="grid"></div><div class="actions"><button class="primary" data-action="start">Start run ↗</button><button data-action="random">🎲 Random Chimpion</button></div></div>`;grid();$('#search').addEventListener('input',grid);$('#segment').addEventListener('change',grid);$('#favoritesOnly').addEventListener('change',grid)}
function grid(){const q=$('#search')?.value.toLowerCase()||'',segment=$('#segment')?.value||'',favoritesOnly=$('#favoritesOnly')?.checked;$('#grid').innerHTML=collection.filter(c=>(c.name+' '+c.segment).toLowerCase().includes(q)&&(!segment||c.segment===segment)&&(!favoritesOnly||data.favorites.includes(c.id))).map(c=>`<div class="card-wrap"><button class="card ${c.id===selected.id?'selected':''}" data-id="${escape(c.id)}" aria-pressed="${c.id===selected.id}">${imageTag(c,'loading="lazy" decoding="async"')}<strong>${escape(c.name)}</strong><small>${escape(c.segment)} · BEST ${pad(data.perCharacter[c.id]?.score||0)}</small></button><button class="favorite" data-fav="${escape(c.id)}" aria-label="${data.favorites.includes(c.id)?'Remove from':'Add to'} favorites">${data.favorites.includes(c.id)?'♥':'♡'}</button></div>`).join('')||'<p>No Chimpions match those filters.</p>'}
function tutorialObstacles(){const pick=id=>({...TYPES.find(x=>x.id===id),passed:false,resolved:'unresolved',minClearance:999});run.obstacles=[{...pick('log'),x:650},{...pick('stump'),x:1450},{...pick('branch'),x:2350}];run.bananas=[{x:650,y:72,golden:false,collected:false},{x:1450,y:125,golden:false,collected:false},{x:2350,y:23,golden:false,collected:false}];run.spawnDistance=3100;run.invulnerable=13;run.notice='SPACE / TAP · JUMP';run.noticeTime=4}
function start(options={}){tone('click');persist();tutorialActive=!data.tutorial&&!options.daily;run=createRun(options.daily?{mode:'daily',seed:dailySeed()}:{mode:'normal'});if(tutorialActive)tutorialObstacles();particles=[];newRecord=false;announcedBest=false;bestMilestones=new Set();runBestBefore=best();runBestDistance=data.runs[0]?.distance||0;countdown=options.fast?.85:1.8;overlay.innerHTML=`<div class="intro"><span>${escape(selected.name)}</span><small>${options.fast?'READY':'CHIMPION ARRIVAL'}</small><div class="countdown" aria-live="polite">${options.fast?'GO!':''}</div></div>`;mode(options.fast?'countdown':'intro');hud();canvas.focus({preventScroll:true})}
const startDaily=()=>start({daily:true});
function pause(){if(!['intro','running','countdown'].includes(state))return;previous=state;mode('paused');overlay.innerHTML='<div class="panel center"><span class="tag">TAKE A BREATHER</span><h2>PAUSED</h2><p>Active time, stages, physics and score are frozen.</p><div class="actions"><button class="primary" data-action="resume">Resume</button><button data-action="restart">Restart</button><button data-action="menu">Quit</button></div></div>'}
function resume(){overlay.innerHTML=previous==='intro'?`<div class="intro"><span>${escape(selected.name)}</span><small>CHIMPION ARRIVAL</small><div class="countdown"></div></div>`:previous==='countdown'?`<div class="intro"><span>${escape(selected.name)}</span><small>READY</small><div class="countdown"></div></div>`:'';mode(previous);canvas.focus({preventScroll:true})}
function unlockAchievements(){const checks=[['first-steps',run.distance>=500,'FIRST STEPS'],['untouchable',run.stage>=5&&run.shieldBreaks===0,'UNTOUCHABLE'],['risk-taker',run.nearMisses>=10,'RISK TAKER'],['chimpion',run.stage>=10,'CHIMPION'],['smooth-operator',run.perfectSlides>=10,'SMOOTH OPERATOR'],['air-time',run.perfectJumps>=15,'AIR TIME'],['going-bananas',data.runs.reduce((n,x)=>n+(x.bananas||0),0)>=100,'GOING BANANAS']];return checks.filter(([id,ok])=>ok&&!data.achievements.includes(id)).map(([id,,name])=>{data.achievements.push(id);return name})}
function gameover(){newRecord=run.score>runBestBefore;const result={score:run.score,distance:run.distance,name:selected.name,id:selected.id,stage:run.stage,bananas:run.bananaCount,maxFlow:run.maxFlow,date:Date.now()};data.runs.push(result);const personal=data.perCharacter[selected.id];if(!personal||run.score>personal.score)data.perCharacter[selected.id]=result;if(newRecord)data.bestSplits=run.splits;if(run.mode==='daily'){const key=new Date().toISOString().slice(0,10);if(!data.daily[key]||run.score>data.daily[key].score)data.daily[key]=result}const unlocked=unlockAchievements();persist();mode('over');tone(newRecord?'record':'dead');overlay.innerHTML=`<div class="panel center results"><span class="tag">${newRecord?'NEW PERSONAL BEST':'RUN COMPLETE'}</span><h2>RUN COMPLETE</h2><p>${escape(selected.name)} · ${run.mode==='daily'?'DAILY JUNGLE':'ENDLESS RUN'}</p><div class="stats"><div><small>SCORE</small><strong>${pad(run.score)}</strong></div><div><small>DISTANCE</small><strong>${(run.distance/1000).toFixed(2)} KM</strong></div><div><small>STAGE</small><strong>${run.stage}</strong></div></div><div class="summary"><span>🍌 ${run.bananaCount}</span><span>FLOW ${flowMultiplier(run.maxFlow).toFixed(2)}×</span><span>COMBO ${run.longestCombo}</span><span>PERFECT ↥ ${run.perfectJumps}</span><span>PERFECT ⇣ ${run.perfectSlides}</span><span>NEAR MISS ${run.nearMisses}</span></div>${unlocked.length?`<div class="record">ACHIEVEMENT: ${unlocked.join(' · ')}</div>`:''}<div class="actions"><button class="primary" data-action="restart">Run again ↗</button><button data-action="choose">Change Chimpion</button><button data-action="share">Share run</button><button data-action="menu">Main menu</button></div></div>`;updateMate()}
function help(){mode('help');overlay.innerHTML='<div class="panel"><h2>RUN WITH FLOW.</h2><div class="help-lines"><p><b>Jump:</b> Space, W, ↑, left click, or the right touch zone. Tap for a low hop; hold for a high jump.<br><b>Slide:</b> ↓, Shift, S, A, right click, or the left touch zone. Hold to stay low.<br><b>Stages:</b> Stage 1 stays welcoming for 30 seconds. Every 30 active seconds, the biome and pace advance.<br>Collect bananas, skim hazards for Perfect actions and Near Misses, build Flow, and trigger Chimpion Mode. A shield saves one collision.</p></div><p class="notice">Scores and achievements stay on this browser. All Chimpions perform identically.</p><button class="primary" data-action="menu">Got it</button></div>'}
function leaderboard(){mode('scores');overlay.innerHTML=`<div class="panel"><h2>MY BEST RUNS</h2><p>Your local top ten · ${data.achievements.length}/7 achievements</p>${data.runs.length?data.runs.sort((a,b)=>b.score-a.score).slice(0,10).map((s,i)=>`<div class="runrow"><span>${i+1}. ${escape(s.name)} · STAGE ${s.stage||1}</span><b>${pad(s.score)} · ${(s.distance/1000).toFixed(2)} km</b></div>`).join(''):'<p>No runs yet. Your first adventure starts here.</p>'}<div class="actions"><button class="primary" data-action="start">Let’s run</button><button data-action="menu">Back</button></div></div>`}
async function shareRun(){const text=`CHIMPIONS DASH — ${selected.name}\n${run.score.toLocaleString()} PTS · ${(run.distance/1000).toFixed(2)} KM · ${run.bananaCount} BANANAS · STAGE ${run.stage}\nCan you beat this run?`;try{const card=document.createElement('canvas');card.width=1200;card.height=630;const x=card.getContext('2d'),g=x.createLinearGradient(0,0,1200,630);g.addColorStop(0,'#092922');g.addColorStop(1,'#58743c');x.fillStyle=g;x.fillRect(0,0,1200,630);x.fillStyle='#eff079';x.font='bold 70px Arial';x.fillText('CHIMPIONS DASH',70,105);x.fillStyle='white';x.font='bold 45px Arial';x.fillText(selected.name.toUpperCase(),70,200);x.font='bold 86px monospace';x.fillText(`${run.score.toLocaleString()} PTS`,70,325);x.font='32px monospace';x.fillText(`${(run.distance/1000).toFixed(2)} KM  ·  ${run.bananaCount} BANANAS  ·  STAGE ${run.stage}`,70,410);x.fillStyle='#eff079';x.fillText('CAN YOU BEAT THIS RUN?',70,535);const blob=await new Promise(resolve=>card.toBlob(resolve,'image/png'));const file=blob?new File([blob],'chimpions-dash-run.png',{type:'image/png'}):null;if(navigator.share&&file&&navigator.canShare?.({files:[file]}))await navigator.share({title:'Chimpions Dash',text,files:[file]});else if(navigator.clipboard){await navigator.clipboard.writeText(text);toast('RUN RESULT COPIED')}else{const a=document.createElement('a');a.download='chimpions-dash-run.png';a.href=card.toDataURL();a.click()}}catch{toast('SHARING IS NOT AVAILABLE HERE')}}
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,1800)}
function selectRandom(){const choices=collection.filter(c=>c.id!==selected.id);selected=choices[Math.floor(Math.random()*choices.length)]||collection[0];persist();grid();updateMate();$('.card.selected')?.scrollIntoView({block:'nearest'})}
const actions={start,daily:startDaily,choose,menu,resume,help,scores:leaderboard,random:selectRandom,restart:()=>start({fast:true,daily:run.mode==='daily'}),share:shareRun};
overlay.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;tone('click');if(b.dataset.fav){const id=b.dataset.fav;data.favorites=data.favorites.includes(id)?data.favorites.filter(x=>x!==id):[...data.favorites,id];persist();grid()}else if(b.dataset.id){selected=collection.find(c=>c.id===b.dataset.id)||selected;persist();grid();updateMate()}else actions[b.dataset.action]?.()});
$('#sound').onclick=()=>{data.sound=!data.sound;tone('click');persist();updateMate()};$('#pause').onclick=pause;$('#chooseBottom').onclick=()=>{if(!['intro','running','countdown'].includes(state))choose()};$('#mate').onclick=$('#chooseBottom').onclick;$('.brand').onclick=e=>{e.preventDefault();menu()};
const jumpKeys=new Set(['Space','ArrowUp','KeyW']),slideKeys=new Set(['ArrowDown','ShiftLeft','ShiftRight','KeyS','KeyA']),heldJump=new Set(),heldSlide=new Set(),pointers=new Map();
function doJump(){if(state==='running'){const launched=jump(run);if(launched){tone('jump');dust()}}}
function doSlide(){if(state==='running'&&slide(run)){tone('slide');syncDashAudio()}}
function releaseControls(){heldJump.clear();heldSlide.clear();pointers.clear();releaseJump(run);releaseSlide(run);voice.setDash?.(false)}
function releasePointer(e){const kind=pointers.get(e.pointerId);if(!kind)return;pointers.delete(e.pointerId);if(kind==='jump'&&![...pointers.values()].includes('jump')&&!heldJump.size)releaseJump(run);if(kind==='slide'&&![...pointers.values()].includes('slide')&&!heldSlide.size){releaseSlide(run);syncDashAudio()}}
canvas.addEventListener('contextmenu',e=>{if(['intro','running','countdown'].includes(state))e.preventDefault()});
canvas.addEventListener('pointerdown',e=>{if(state!=='running'||pointers.has(e.pointerId))return;const rect=canvas.getBoundingClientRect(),kind=e.pointerType==='mouse'?(e.button===2?'slide':e.button===0?'jump':null):(e.clientX-rect.left<rect.width/2?'slide':'jump');if(!kind)return;e.preventDefault();pointers.set(e.pointerId,kind);try{canvas.setPointerCapture(e.pointerId)}catch{}kind==='jump'?doJump():doSlide()});
for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,releasePointer);window.addEventListener('pointerup',releasePointer);
for(const [id,kind] of [['touchSlide','slide'],['touchJump','jump']]){const el=$('#'+id);el.addEventListener('pointerdown',e=>{if(state!=='running')return;e.preventDefault();pointers.set(e.pointerId,kind);kind==='jump'?doJump():doSlide()});for(const event of ['pointerup','pointercancel'])el.addEventListener(event,releasePointer)}
window.addEventListener('keydown',e=>{if(e.target?.matches?.('input,select,textarea'))return;if(jumpKeys.has(e.code)&&['intro','running','countdown'].includes(state)){e.preventDefault();if(state==='running'&&!e.repeat){heldJump.add(e.code);doJump()}}if(slideKeys.has(e.code)&&['intro','running','countdown'].includes(state)){e.preventDefault();if(state==='running'&&!e.repeat){heldSlide.add(e.code);doSlide()}}if(['KeyP','Escape'].includes(e.code)&&!e.repeat){if(state==='paused')resume();else pause()}if(e.code==='Backquote'&&state==='running')run.debug=!run.debug});
window.addEventListener('keyup',e=>{heldJump.delete(e.code);heldSlide.delete(e.code);if(!heldJump.size&&![...pointers.values()].includes('jump'))releaseJump(run);if(!heldSlide.size&&![...pointers.values()].includes('slide')){releaseSlide(run);syncDashAudio()}});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});window.addEventListener('blur',pause);
function hud(){const biome=BIOMES[(run.stage-1)%BIOMES.length][0];$('#score').textContent=pad(run.score);$('#distance').textContent=(run.distance/1000).toFixed(2)+' KM';$('#best').textContent=pad(Math.max(runBestBefore,run.score));$('#power').hidden=!(run.shield&&state==='running');$('#bananas').textContent=`🍌 ${run.bananaCount}${run.goldenBananas?' · ✦ '+run.goldenBananas:''}`;$('#flow').textContent=`FLOW ${flowMultiplier(run.flow).toFixed(2)}×`;$('#pace').textContent=paceText();$('#jumpHint').textContent=run.noticeTime>0?run.notice:'';$('#jumpHint').hidden=!run.noticeTime;$('.world-label').textContent=`${String(run.stage).padStart(2,'0')} / ${biome}`;$('#flowBar').style.width=run.flow+'%';document.body.dataset.biome=String((run.stage-1)%8)}
function paceText(){const split=data.bestSplits[Math.max(0,Math.floor(run.time)-1)];if(!split)return`${(run.speed/265).toFixed(2)}× PACE`;const diff=run.distance-split.distance;return`${diff>=0?'▲':'▼'} ${Math.abs(diff).toFixed(0)}M ${diff>=0?'AHEAD':'BEHIND'}`}
function dust(label,color){for(let i=0;i<6;i++)particles.push({x:PLAYER_X,y:5,vx:-40-Math.random()*70,vy:Math.random()*60,life:.4,size:3+Math.random()*3,color});if(label)particles.push({x:PLAYER_X+20,y:80,vx:0,vy:38,life:.8,label,color})}
function tutorialUpdate(){if(!tutorialActive)return;if(run.time<4){run.notice='SPACE / TAP · JUMP';run.noticeTime=.2}else if(run.time<8){run.notice='HOLD JUMP · JUMP HIGHER';run.noticeTime=.2}else if(run.time<13){run.notice='↓ / SHIFT / LEFT TOUCH · SLIDE';run.noticeTime=.2}else{tutorialActive=false;data.tutorial=true;run.invulnerable=0;run.notice='YOU GOT IT.';run.noticeTime=1.4;persist()}}
function loop(now){if(!['intro','running','countdown'].includes(state))return;const dt=last?Math.min((now-last)/1000,.1):0;last=now;if(state==='intro'){const before=run.introTime;run.introTime+=dt;if(before<1.16&&run.introTime>=1.16)tone('power');if(run.introTime>=2.55){state='countdown';overlay.dataset.mode='countdown';countdown=1.8;overlay.innerHTML=`<div class="intro"><span>${escape(selected.name)}</span><small>READY</small><div class="countdown" aria-live="polite">2</div></div>`;tone('stage')}}else if(state==='countdown'){countdown-=dt;const el=$('.countdown');if(el)el.textContent=countdown>.45?Math.ceil(countdown-.45):'GO!';if(countdown<=0){overlay.innerHTML='';overlay.dataset.mode='running';state='running';acc=0}}else{acc+=dt;while(acc>=STEP){const events=step(run,STEP);acc-=STEP;syncDashAudio();if(run.y===0&&(run.slideHeld||run.slideMin>0)&&Math.random()<.34)particles.push({x:PLAYER_X-8,y:6,vx:-90-Math.random()*90,vy:10+Math.random()*45,life:.32,size:3+Math.random()*4,color:'#c8c092'});tutorialUpdate();for(const event of events){if(event==='dead'){gameover();return}tone(event);if(event==='land')dust();if(event==='banana')dust('+25','#ffe175');if(event==='golden')dust('GOLDEN +500','#fff176');if(event==='shield-used'){dust('SHIELD SAVED YOU','#a5ffe4');try{navigator.vibrate?.(35)}catch{}}if(['PERFECT JUMP','PERFECT SLIDE','CLOSE CALL','chimpion-mode','stage'].includes(event))dust(event.toUpperCase(),'#eff079')}for(const p of particles){p.life-=STEP;p.x+=p.vx*STEP;p.y+=p.vy*STEP;p.vy-=180*STEP}particles=particles.filter(p=>p.life>0);if(runBestDistance>0){const remaining=runBestDistance-run.distance;for(const mark of [100,50,10])if(remaining<=mark&&remaining>0&&!bestMilestones.has(mark)){bestMilestones.add(mark);run.notice=`${mark} M TO YOUR BEST`;run.noticeTime=1.1}}if(!announcedBest&&runBestBefore>0&&run.score>runBestBefore){announcedBest=true;run.notice='NEW PERSONAL BEST!';run.noticeTime=1.8;tone('record')}}}draw();hud();raf=requestAnimationFrame(loop)}
function resize(){renderer.resize()}function draw(){renderer.draw(state,run,selected,particles)}
window.addEventListener('resize',resize);window.addEventListener('orientationchange',()=>setTimeout(resize,120));updateMate();menu();resize();
async function loadCollection(){try{const response=await fetch('collection.json',{signal:AbortSignal.timeout?.(6000)});if(!response.ok)throw Error('collection');const raw=await response.json();if(!Array.isArray(raw))throw Error('collection');const clean=raw.filter(c=>c&&typeof c.id==='string'&&typeof c.name==='string'&&typeof c.image==='string'&&(/^(https:\/\/|assets\/)/.test(c.image)));if(!clean.length)throw Error('empty');collection=clean}catch{collection=fallback}selected=collection.find(c=>c.id===data.selected)||collection[0];$('#count').textContent=collection.length+' CHIMPIONS';updateMate();if(state==='menu')menu();else if(state==='choose')choose()}
loadCollection();
